-- Carga desde Tiendanube: SS26 (58 prendas → "Colecciones anteriores") y Lencería (47 prendas → "Lencería").
-- Solo productos visibles en Tiendanube y talles con stock 1 o más (sin stock infinito, sin packs).
-- Primero borra lo cargado antes desde Tiendanube (ids tn-...). Pegar en Supabase → SQL Editor → Run. Se puede correr más de una vez.
delete from productos where id like 'tn-%' and showroom_id = (select id from showrooms where slug = 'egoh');
insert into productos (showroom_id, id, orden, data)
